text:
{
  "items": [
    {
      "index": 1,
      "combo": "A",
      "scene": "公共交通出行（票价、站数、乘车人数）",
      "angle": "将不同线路的公交票价转换为小数形式，并比较哪条线路更便宜。",
      "roles": {
        "结合元角分认识小数": "将几元几角几分转化为以元为单位的小数",
        "万以内数比较大小": "比较转化后的小数数值大小，判断价格高低"
      }
    },
    {
      "index": 2,
      "combo": "A",
      "scene": "科学实验与测量（体积变化、质量、时间）",
      "angle": "读取刻度尺上不足整厘米的长度数据，用毫米辅助表示为小数。",
      "roles": {
        "结合米制单位认识小数": "理解米、分米、厘米、毫米之间的十进关系并写成小数",
        "毫米和分米的认识": "准确读取毫米刻度，作为小数末尾位数的依据"
      }
    },
    {
      "index": 3,
      "combo": "A",
      "scene": "校园绿化与植树（棵数、间隔距离、总面积）",
      "angle": "已知花坛总面积，先求其中一种花的占地面积，再求该区域内特定品种的数量。",
      "roles": {
        "整数乘分数（求一个数的几分之几是多少）": "第一步：用总面积乘以分数，求出某类植物的种植区域面积",
        "分数乘分数": "第二步：在该区域面积基础上，再乘以另一个分数，求最终特定品种的面积"
      }
    },
    {
      "index": 4,
      "combo": "A",
      "scene": "公平游戏与概率（可能性大小、次数、概率）",
      "angle": "分析转盘游戏中指针落在不同颜色区域的可能性，并解释分数含义。",
      "roles": {
        "平均分的两种情况（等分与包含）": "理解将圆盘整体“等分”成若干份的过程，确定总份数",
        "分数的意义（单位“1”与分数单位）": "将某种颜色区域的份数表示为占总份数（单位“1”）的几分之几"
      }
    },
    {
      "index": 5,
      "combo": "A",
      "scene": "体育比赛计分（得分、场次、平均分）",
      "angle": "根据比赛奖金数额，分析其数位组成，并换算为带小数的金额。",
      "roles": {
        "万以内数的数位顺序与组成": "分析大额整数的各个数位值，理解数值的构成",
        "结合元角分认识小数": "将整数金额或带有零头的金额准确表述为元角分对应的小数形式"
      }
    },
    {
      "index": 6,
      "combo": "A",
      "scene": "身高体重与健康（身高、体重、年龄）",
      "angle": "记录多名同学的身高数据（含厘米），转换为米为单位的小数并排序。",
      "roles": {
        "结合米制单位认识小数": "将厘米部分转化为米的小数部分（如145cm=1.45m）",
        "万以内数比较大小": "通过比较小数的大小，确定身高的从高到低顺序"
      }
    }
  ]
}
